static int failures = 0;

#define CHECK(cond)                                                          \
    do {                                                                     \
        if (!(cond)) {                                                       \
            std::printf("FAIL  %s:%d  %s\n", __FILE__, __LINE__, #cond);     \
            ++failures;                                                      \
        }                                                                    \
    } while (0)

static Tick tick(std::int64_t ts, std::int64_t price){
    return Tick{ts, price, 1, Operation::execute};
}

// ---------------------------------------------------------------------------
// 1. Hand-written edge cases
// ---------------------------------------------------------------------------

static void empty_and_single(){
    RollingMax<10> m;
    CHECK(!m.get_max().has_value());
    m.on_tick(tick(100, 7));
    CHECK(m.get_max() == 7);
}

static void rising_prices(){
    RollingMax<10> m;
    for (std::int64_t i = 0; i < 20; ++i){
        m.on_tick(tick(i, 100 + i));
        CHECK(m.get_max() == 100 + i);          // the newest is always the max
    }
}

static void falling_prices(){
    // W = 10, one tick per ns, prices 100, 99, 98, ...
    // At ts = t the window is [t - 10, t], so the max is the price at t - 10 once t >= 10.
    RollingMax<10> m;
    for (std::int64_t t = 0; t < 30; ++t){
        m.on_tick(tick(t, 100 - t));
        const std::int64_t oldest = t < 10 ? 0 : t - 10;
        CHECK(m.get_max() == 100 - oldest);
    }
}

static void window_boundary(){
    {   // exactly W old: still in the window
        RollingMax<10> m;
        m.on_tick(tick(0, 50));
        m.on_tick(tick(10, 1));
        CHECK(m.get_max() == 50);
    }
    {   // W + 1 old: evicted
        RollingMax<10> m;
        m.on_tick(tick(0, 50));
        m.on_tick(tick(11, 1));
        CHECK(m.get_max() == 1);
    }
}

static void equal_prices(){
    // The older 50 expires; the newer 50 must still hold the max.
    RollingMax<10> m;
    m.on_tick(tick(0, 50));
    m.on_tick(tick(5, 50));
    m.on_tick(tick(6, 10));
    CHECK(m.get_max() == 50);
    m.on_tick(tick(11, 10));                    // ts 0 expires, ts 5 stays
    CHECK(m.get_max() == 50);
    m.on_tick(tick(16, 10));                    // ts 5 expires
    CHECK(m.get_max() == 10);
}

static void late_ticks(){
    RollingMax<10> m;
    m.on_tick(tick(100, 20));
    m.on_tick(tick(99, 999));                   // late and higher: dropped
    CHECK(m.get_max() == 20);
    m.on_tick(tick(50, 1));                     // late, far outside: dropped
    CHECK(m.get_max() == 20);
    m.on_tick(tick(105, 30));                   // later ticks still correct
    CHECK(m.get_max() == 30);
    m.on_tick(tick(116, 5));                    // 100 and 105 both expired
    CHECK(m.get_max() == 5);
}

static void equal_timestamps(){
    RollingMax<10> m;
    m.on_tick(tick(100, 20));
    m.on_tick(tick(100, 40));                   // same ts: accepted
    m.on_tick(tick(100, 30));
    CHECK(m.get_max() == 40);
    m.on_tick(tick(111, 1));                    // all three expire together
    CHECK(m.get_max() == 1);
}

static void negative_prices(){
    RollingMax<10> m;
    m.on_tick(tick(0, -5));
    CHECK(m.get_max() == -5);
    m.on_tick(tick(1, -9));
    CHECK(m.get_max() == -5);
    m.on_tick(tick(12, -9));                    // -5 expired
    CHECK(m.get_max() == -9);
}

static void long_gap(){
    RollingMax<1'000> m;
    for (std::int64_t t = 0; t < 100; ++t)
        m.on_tick(tick(t, 1'000 - t));
    m.on_tick(tick(1'000'000'000, 1));          // everything before is long gone
    CHECK(m.get_max() == 1);
}

static void zero_window(){
    // W = 0: only ticks with the same timestamp share a window
    RollingMax<0> m;
    m.on_tick(tick(10, 5));
    m.on_tick(tick(10, 3));
    CHECK(m.get_max() == 5);
    m.on_tick(tick(11, 3));
    CHECK(m.get_max() == 3);
}

static void stale_without_ticks(){
    // Eviction only runs inside on_tick(): with no new tick, the max does not change.
    // This documents the current behaviour; it is not a requirement.
    RollingMax<10> m;
    m.on_tick(tick(0, 42));
    CHECK(m.get_max() == 42);
    CHECK(m.get_max() == 42);
}

// ---------------------------------------------------------------------------
// 2. Reference comparison on the generator corpus
// ---------------------------------------------------------------------------

// Independent reference: accepted ticks in a vector, prices in the window in a multiset,
// moved forward with two pointers. Same rules as above, different algorithm.
class ReferenceMax{
    public:
    explicit ReferenceMax(std::int64_t w) : _w(w) {}

    void on_tick(const Tick& t){
        if (!_accepted.empty() && t.ts_ns < _accepted.back().ts_ns)
            return;                                         // late: dropped
        _accepted.push_back(t);
        _prices.insert(t.price);
        while (_accepted[_first].ts_ns < t.ts_ns - _w)
            _prices.erase(_prices.find(_accepted[_first++].price));
    }

    std::optional<std::int64_t> get_max() const{
        if (_prices.empty())
            return std::nullopt;
        return *_prices.rbegin();
    }

    std::size_t live() const { return _prices.size(); }

    private:
    std::int64_t _w;
    std::vector<Tick> _accepted;
    std::size_t _first = 0;
    std::multiset<std::int64_t> _prices;
};

template <std::int64_t W>
static void compare_with_reference(const std::vector<Tick>& ticks, const char* label){
    RollingMax<W> m;
    ReferenceMax ref(W);
    std::size_t mismatches = 0, peak = 0, dropped = 0;
    std::int64_t last_ts = INT64_MIN;

    for (std::size_t i = 0; i < ticks.size(); ++i){
        if (ticks[i].ts_ns < last_ts)
            ++dropped;
        else
            last_ts = ticks[i].ts_ns;

        m.on_tick(ticks[i]);
        ref.on_tick(ticks[i]);
        if (m.get_max() != ref.get_max()){
            if (mismatches < 5)
                std::printf("FAIL  %s W=%lld: tick %zu ts %lld: got %lld, reference %lld\n",
                            label, static_cast<long long>(W), i,
                            static_cast<long long>(ticks[i].ts_ns),
                            static_cast<long long>(m.get_max().value_or(-1)),
                            static_cast<long long>(ref.get_max().value_or(-1)));
            ++mismatches;
        }
        if (ref.live() > peak)
            peak = ref.live();
    }

    if (mismatches)
        ++failures;
    std::printf("%s  %-8s W=%-12lld ticks %zu  dropped %zu  mismatches %zu  peak window %zu\n",
                mismatches ? "FAIL" : "ok  ", label, static_cast<long long>(W),
                ticks.size(), dropped, mismatches, peak);
}

template <std::int64_t W>
static void reference_suite(const std::vector<Tick>& in_order, const std::vector<Tick>& with_late){
    compare_with_reference<W>(in_order, "in-order");
    compare_with_reference<W>(with_late, "late");
}

int main(){
    empty_and_single();
    rising_prices();
    falling_prices();
    window_boundary();
    equal_prices();
    late_ticks();
    equal_timestamps();
    negative_prices();
    long_gap();
    zero_window();
    stale_without_ticks();
    std::printf("%s  edge cases\n", failures ? "FAIL" : "ok  ");

    const std::vector<Tick> in_order = TickGenerator::corpus(200'000);

    // Every 97th tick swapped with the next one, so the later one arrives first
    std::vector<Tick> with_late = in_order;
    for (std::size_t i = 0; i + 1 < with_late.size(); i += 97)
        std::swap(with_late[i], with_late[i + 1]);

    reference_suite<1'000'000>(in_order, with_late);           // 1 ms
    reference_suite<1'000'000'000>(in_order, with_late);       // 1 s
    reference_suite<30'000'000'000>(in_order, with_late);      // 30 s

    if (failures){
        std::printf("rolling-max regression: FAILED\n");
        return EXIT_FAILURE;
    }
    std::printf("rolling-max regression: PASSED\n");
    return EXIT_SUCCESS;
}
